import{_ as t,o as a,c as r,a2 as d}from"./chunks/framework.BetZR81g.js";const h=JSON.parse('{"title":"API Guide","description":"","frontmatter":{"lang":"en","sourcePath":"docs/api.md"},"headers":[],"relativePath":"guide/api.md","filePath":"guide/api.md"}'),o={name:"guide/api.md"};function s(i,e,n,c,p,l){return a(),r("div",null,[...e[0]||(e[0]=[d('<h1 id="api-guide" tabindex="-1">API Guide <a class="header-anchor" href="#api-guide" aria-label="Permalink to &quot;API Guide&quot;">​</a></h1><blockquote><p>sfml.js is based on SFML 3.1.0. The handwritten guides explain usage, return values and Node.js adaptations; <a href="/reference/" target="_self">TypeDoc</a> generates complete signatures and type constraints from the source.</p></blockquote><p><a href="/guide/">Documentation</a> · <a href="/guide/getting-started">Quick start</a> · <a href="/guide/concepts">Core concepts</a></p><p>Import all public APIs from <code>sfml.js</code>; see <a href="https://github.com/XadillaX/node-sfml/blob/main/src/index.ts" target="_blank" rel="noreferrer">src/index.ts</a> for the export list. Application code does not need to access <code>dist/internal</code> or native module handles.</p><h2 id="choose-by-task" tabindex="-1">Choose by task <a class="header-anchor" href="#choose-by-task" aria-label="Permalink to &quot;Choose by task&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Task</th><th>Guide</th><th>Main APIs</th></tr></thead><tbody><tr><td>Calculate coordinates, angles and frame times</td><td><a href="/guide/system">System</a></td><td>Vector2/3, Angle, Time, Clock, named operators</td></tr><tr><td>Integrate custom file sources</td><td><a href="/guide/system#input-streams">Input streams</a></td><td>InputStream, MemoryInputStream, FileInputStream</td></tr><tr><td>Open windows and receive input</td><td><a href="/guide/window">Window</a></td><td>RenderWindow, Window, Event, Keyboard, Mouse</td></tr><tr><td>Display images and animation</td><td><a href="/guide/graphics">Graphics</a></td><td>Image, Texture, Sprite</td></tr><tr><td>Draw shapes and text</td><td><a href="/guide/graphics">Graphics</a></td><td>Shape, Font, Glyph, Text</td></tr><tr><td>Cameras, off-screen composition and batched geometry</td><td><a href="/guide/graphics">Graphics</a></td><td>View, RenderTexture, VertexArray, VertexBuffer</td></tr><tr><td>Custom drawing and shaders</td><td><a href="/guide/graphics">Graphics</a></td><td>Drawable, RenderStates, Shader, Glsl</td></tr><tr><td>Play, record and process audio</td><td><a href="/guide/audio">Audio</a></td><td>SoundBuffer, Sound, Music, SoundStream, SoundRecorder</td></tr><tr><td>Connect to networks and transfer files</td><td><a href="/guide/network">Network</a></td><td>Packet, TcpSocket, UdpSocket, Http, Ftp, Sftp</td></tr></tbody></table><h2 id="system" tabindex="-1">System <a class="header-anchor" href="#system" aria-label="Permalink to &quot;System&quot;">​</a></h2><p><code>Vector2</code>/<code>Vector3</code> support multiple scalar types; <code>Vector2i/u/f</code> and <code>Vector3i/u/f</code> are common specializations. <code>degrees()</code>/<code>radians()</code> create an Angle, and time factories create a Time.</p><p>JavaScript does not support C++ operator overloading, so use <code>add()</code>, <code>multiply()</code>, <code>equal()</code> and <code>*Assign()</code> for the corresponding operations. This module also includes <code>Clock</code>, asynchronous <code>sleep()</code>, <code>TimeoutWithPredicate</code>, input streams, <code>Unicode</code> and error logging APIs.</p><p>See <a href="/guide/system">System</a>.</p><h2 id="window" tabindex="-1">Window <a class="header-anchor" href="#window" aria-label="Permalink to &quot;Window&quot;">​</a></h2><p><code>Window</code> provides a system window and an OpenGL context. For 2D drawing, use <code>RenderWindow</code>, which combines Window and RenderTarget capabilities.</p><p>Receive events through <code>pollEvent()</code>, <code>handleEvents()</code> or synchronous <code>waitEvent()</code>. Keyboard, mouse, joystick and sensor APIs also provide real-time queries. <code>Clipboard</code>, <code>Cursor</code>, <code>Context</code> and <code>Vulkan</code> cover system integration.</p><p>See <a href="/guide/window">Window</a>.</p><h2 id="graphics" tabindex="-1">Graphics <a class="header-anchor" href="#graphics" aria-label="Permalink to &quot;Graphics&quot;">​</a></h2><p>Image stores CPU-side pixels, Texture stores a GPU texture, and Sprite references a texture for drawing. Shape provides circles, rectangles, convex polygons and custom convex shapes; Font and Text provide font loading, layout and editable vertices.</p><p>RenderTarget unifies drawing APIs for windows and off-screen targets. View controls the camera and viewport; RenderStates controls transforms, blending, stencil settings, textures and shaders. Vertex arrays and GPU vertex buffers let you organize geometry directly.</p><p>See <a href="/guide/graphics">Graphics</a> and <a href="/guide/concepts#draw-snapshots">draw snapshots</a>.</p><h2 id="audio" tabindex="-1">Audio <a class="header-anchor" href="#audio" aria-label="Permalink to &quot;Audio&quot;">​</a></h2><p>Use SoundBuffer + Sound for short effects and Music for long audio. SoundSource provides volume, panning and spatial audio properties; SoundStream, SoundRecorder and EffectProcessor use Worker callbacks to process custom data.</p><p>See <a href="/guide/audio">Audio</a>, paying particular attention to sample counts, channel layout and buffer lifetime.</p><h2 id="network" tabindex="-1">Network <a class="header-anchor" href="#network" aria-label="Permalink to &quot;Network&quot;">​</a></h2><p>Network implements SFML-style APIs using Node.js transports; production code does not call SFML C++ Network. Packet preserves SFML encoding conventions; TCP, UDP, DNS, TLS, HTTP, FTP and SFTP I/O use promises.</p><p>See <a href="/guide/network">Network</a> for returned statuses, partial sends, protocol limits and shutdown methods.</p><h2 id="compatibility-boundaries" tabindex="-1">Compatibility boundaries <a class="header-anchor" href="#compatibility-boundaries" aria-label="Permalink to &quot;Compatibility boundaries&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Feature</th><th>Current behavior</th></tr></thead><tbody><tr><td>C++ pointers and reference output parameters</td><td>Represented as objects, views or returned objects</td></tr><tr><td>C++ templates and operators</td><td>Represented by explicit scalar tags, classes and named functions</td></tr><tr><td>File loading</td><td>Uses promises, preserving each API&#39;s specific failure status</td></tr><tr><td>Destruction</td><td>Native ownership works with JS references; explicitly close resources that expose a close method</td></tr><tr><td><code>drawAsync()</code>/<code>displayAsync()</code></td><td>Not provided; legacy examples explicitly report them as unsupported</td></tr><tr><td>Android SuspendAwareClock</td><td>Conditionally compiled API; the current download flow targets desktops</td></tr><tr><td>Vulkan</td><td>Query APIs are exported; availability depends on the SFML platform backend, with no macOS backend</td></tr></tbody></table><p>See the <a href="/guide/development#testing">development guide</a> for platform build and test coverage.</p><p><a id="sfml-cpp-reference"></a></p><h2 id="sfml-c-reference" tabindex="-1">SFML C++ reference <a class="header-anchor" href="#sfml-c-reference" aria-label="Permalink to &quot;SFML C++ reference&quot;">​</a></h2><p><a href="/reference/" target="_self">TypeDoc</a> is the authority for JavaScript signatures and types. The <a href="https://www.sfml-dev.org/documentation/3.1.0/" target="_blank" rel="noreferrer">SFML 3.1.0 reference index</a> is the authority for upstream C++ concepts, not a drop-in JavaScript API reference.</p><p>Each module guide links to relevant C++ classes and explains binding-specific differences: <a href="/guide/system#sfml-cpp-reference">System</a>, <a href="/guide/window#sfml-cpp-reference">Window</a>, <a href="/guide/graphics#sfml-cpp-reference">Graphics</a>, <a href="/guide/audio#sfml-cpp-reference">Audio</a> and <a href="/guide/network#sfml-cpp-reference">Network</a>.</p>',31)])])}const f=t(o,[["render",s]]);export{h as __pageData,f as default};
